// Command rangegen writes random programs that nest range-over-func loops with every kind of
// jump (break, continue, return, goto, labels, defer) and print a trace of what ran. Both Go and
// gocpp must print the same trace, so the programs are differential tests of the lowering of
// range over functions (Phase 07, step 7.8; tests/run/rangefunc_gen_*.gp are generated by it).
//
//	go run ./tools/rangegen -seed 1 -count 30 -out /tmp/gen          # writes /tmp/gen/prog_1.go ...
//	go run ./tools/rangegen -tests tests/run -first 1 -count 30      # writes tests/run/rangefunc_gen_NN.gp
//	                                                                 # with the // Output: block that real Go prints
//
// A program is a few iterators (one that yields ints, one that yields an int and a string, one
// that yields nothing, each tracing its own steps and a deferred cleanup) and some functions that
// are a random nest of range-over-func loops, 3-clause and range-over-int loops and switches,
// whose bodies hold trace prints, ifs, jumps to labeled statements, gotos to the end of a block,
// to the end of the function and back to its start (counted, so it ends), returns, defers and
// closures that keep a loop variable. Every program is valid Go: a label exists only if a jump
// uses it, a goto never jumps over a declaration, and a function ends with a return.
package main

import (
	"bytes"
	"flag"
	"fmt"
	"math/rand"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func main() {
	seed := flag.Int64("seed", 1, "the seed of the first program")
	count := flag.Int("count", 30, "the number of programs")
	out := flag.String("out", "", "write prog_N.go files into this folder")
	tests := flag.String("tests", "", "write rangefunc_gen_NN.gp tests (with the output of real Go) into this folder")
	first := flag.Int("first", 1, "the number of the first test (with -tests)")
	funcs := flag.Int("funcs", 6, "the functions of a program")
	flag.Parse()
	for i := range *count {
		g := &gen{rng: rand.New(rand.NewSource(*seed + int64(i)))}
		src := g.program(*funcs)
		switch {
		case *out != "":
			must(os.MkdirAll(*out, 0o755))
			must(os.WriteFile(filepath.Join(*out, fmt.Sprintf("prog_%d.go", *seed+int64(i))), []byte(src), 0o644))
		case *tests != "":
			n := *first + i
			text := fmt.Sprintf("// phase: 07\n\n%s", src)
			output := runGo(src)
			text += "\n// Output:\n" + commentLines(output)
			must(os.WriteFile(filepath.Join(*tests, fmt.Sprintf("rangefunc_gen_%02d.gp", n)), []byte(text), 0o644))
		default:
			fmt.Print(src)
		}
	}
}

func must(err error) {
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
}

// runGo runs the program with real Go and returns its output.
func runGo(src string) string {
	dir, err := os.MkdirTemp("", "rangegen")
	must(err)
	defer os.RemoveAll(dir)
	must(os.WriteFile(filepath.Join(dir, "main.go"), []byte(src), 0o644))
	must(os.WriteFile(filepath.Join(dir, "go.mod"), []byte("module rangegen\n\ngo 1.25\n"), 0o644))
	cmd := exec.Command("go", "run", ".")
	cmd.Dir = dir
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	if err := cmd.Run(); err != nil {
		fmt.Fprintf(os.Stderr, "go run failed: %v\n%s\n%s", err, stderr.String(), src)
		os.Exit(1)
	}
	return stdout.String()
}

func commentLines(s string) string {
	var b strings.Builder
	for _, l := range strings.Split(strings.TrimRight(s, "\n"), "\n") {
		if l == "" {
			b.WriteString("//\n")
		} else {
			b.WriteString("// " + l + "\n")
		}
	}
	return b.String()
}

// A label is a statement that a jump can name.
type label struct {
	name   string
	loop   bool // continue works too
	used   bool
	isFunc bool // the function's own end or start
}

type gen struct {
	rng    *rand.Rand
	id     int      // numbers the events, the loops and the labels
	stack  []*label // the enclosing statements that break names, innermost last
	blocks []*label // the labels at the end of the enclosing blocks (goto), innermost last
	inRF   int      // the range-over-func loops around the code
	fn     *fnInfo
}

type fnInfo struct {
	named    bool
	end, top *label
	usedTop  bool
	usedEnd  bool
}

func (g *gen) next() int {
	g.id++
	return g.id
}

func (g *gen) chance(p int) bool { return g.rng.Intn(100) < p }

func (g *gen) program(nfuncs int) string {
	var b strings.Builder
	b.WriteString(prelude)
	for i := range nfuncs {
		b.WriteString(g.function(i))
	}
	b.WriteString("\nfunc run(name string, f func() int) {\n\tdefer func() {\n\t\tif r := recover(); r != nil {\n\t\t\tfmt.Println(name, \"recovered\", r)\n\t\t}\n\t}()\n\tfmt.Println(name, \"=\", f())\n}\n\nfunc main() {\n")
	for i := range nfuncs {
		fmt.Fprintf(&b, "\trun(\"f%d\", f%d)\n", i, i)
	}
	b.WriteString("}\n")
	return b.String()
}

const prelude = `package main

import "fmt"

// it1 yields 0..n-1; the body may stop it.
func it1(n int) func(yield func(int) bool) {
	return func(yield func(int) bool) {
		defer fmt.Println("it1 done", n)
		for i := 0; i < n; i++ {
			if !yield(i) {
				fmt.Println("it1 stopped at", i)
				return
			}
		}
	}
}

// it2 yields an int and a string.
func it2(n int) func(yield func(int, string) bool) {
	return func(yield func(int, string) bool) {
		defer fmt.Println("it2 done", n)
		for i := 0; i < n; i++ {
			if !yield(i*10, fmt.Sprint("s", i)) {
				fmt.Println("it2 stopped at", i)
				return
			}
		}
	}
}

// it0 yields nothing but calls the body n times.
func it0(n int) func(yield func() bool) {
	return func(yield func() bool) {
		defer fmt.Println("it0 done", n)
		for i := 0; i < n; i++ {
			if !yield() {
				fmt.Println("it0 stopped at", i)
				return
			}
		}
	}
}

`

// function writes the function fI: a random nest.
func (g *gen) function(i int) string {
	g.fn = &fnInfo{named: g.chance(50), end: &label{name: "end", isFunc: true}, top: &label{name: "top", isFunc: true}}
	g.stack, g.blocks, g.inRF = nil, nil, 0
	g.blocks = []*label{g.fn.end}
	var body strings.Builder
	n := 2 + g.rng.Intn(3)
	for range n {
		body.WriteString(g.stmt(1))
	}
	var b strings.Builder
	if g.fn.named {
		fmt.Fprintf(&b, "func f%d() (res int) {\n", i)
	} else {
		fmt.Fprintf(&b, "func f%d() int {\n", i)
	}
	b.WriteString("\tacc, steps := 0, 0\n\t_ = steps\n")
	if g.chance(40) {
		b.WriteString("\tdefer func() { fmt.Println(\"deferred acc\", acc) }()\n")
	}
	if g.fn.usedTop {
		b.WriteString("top:\n\tsteps++\n\tif steps > 3 {\n\t\tgoto end\n\t}\n")
		g.fn.usedEnd = true
	}
	b.WriteString(body.String())
	if g.fn.usedEnd {
		b.WriteString("end:\n")
	}
	if g.fn.named {
		b.WriteString("\tres = acc\n\treturn\n}\n\n")
	} else {
		b.WriteString("\treturn acc\n}\n\n")
	}
	return b.String()
}

func indent(s string) string {
	lines := strings.Split(strings.TrimRight(s, "\n"), "\n")
	for i, l := range lines {
		if l != "" && !strings.HasSuffix(l, ":") {
			lines[i] = "\t" + l
		} else if l != "" {
			lines[i] = l // labels stay at the margin of their block, as gofmt does one level out
		}
	}
	return strings.Join(lines, "\n") + "\n"
}

// block returns the statements of a block (a loop body or a branch), with a label at its end if a
// goto uses it.
func (g *gen) block(depth int, withEnd bool) string {
	var end *label
	if withEnd {
		end = &label{name: fmt.Sprintf("b%d", g.next())}
		g.blocks = append(g.blocks, end)
	}
	var b strings.Builder
	n := 1 + g.rng.Intn(3)
	if depth >= 4 {
		n = 1
	}
	for range n {
		b.WriteString(g.stmt(depth))
	}
	if withEnd {
		g.blocks = g.blocks[:len(g.blocks)-1]
		if end.used {
			b.WriteString(end.name + ":\n")
		}
	}
	return b.String()
}

func (g *gen) event(vars ...string) string {
	args := fmt.Sprintf("\"e%d\"", g.next())
	for _, v := range vars {
		args += ", " + v
	}
	return fmt.Sprintf("fmt.Println(%s)\n", args)
}

func (g *gen) cond(vars []string) string {
	v := "acc"
	if len(vars) > 0 && g.chance(80) {
		v = vars[g.rng.Intn(len(vars))]
	}
	switch g.rng.Intn(4) {
	case 0:
		return fmt.Sprintf("%s%%2 == %d", v, g.rng.Intn(2))
	case 1:
		return fmt.Sprintf("%s == %d", v, g.rng.Intn(4))
	case 2:
		return fmt.Sprintf("%s > %d", v, g.rng.Intn(4))
	}
	return fmt.Sprintf("%s%%3 == %d", v, g.rng.Intn(3))
}

// jump returns a jump statement (never nil: a trace print if nothing can be done here).
func (g *gen) jump(vars []string) string {
	switch g.rng.Intn(10) {
	case 0, 1: // an unlabeled break or continue
		if len(g.stack) > 0 {
			inner := g.stack[len(g.stack)-1]
			_ = inner
			if g.chance(50) {
				return "break\n"
			}
			// continue goes to the innermost loop, which may be below a switch
			for i := len(g.stack) - 1; i >= 0; i-- {
				if g.stack[i].loop {
					return "continue\n"
				}
			}
			return "break\n"
		}
	case 2, 3, 4: // a labeled break or continue
		if len(g.stack) > 0 {
			l := g.stack[g.rng.Intn(len(g.stack))]
			l.used = true
			if l.loop && g.chance(50) {
				return "continue " + l.name + "\n"
			}
			return "break " + l.name + "\n"
		}
	case 5, 6: // return
		if g.fn.named {
			if g.chance(50) {
				return "res = acc + " + fmt.Sprint(g.rng.Intn(100)) + "\nreturn\n"
			}
			return fmt.Sprintf("return acc + %d\n", g.rng.Intn(100))
		}
		return fmt.Sprintf("return acc + %d\n", g.rng.Intn(100))
	case 7, 8: // goto
		switch g.rng.Intn(4) {
		case 0:
			g.fn.usedTop = true
			return "goto top\n"
		case 1:
			g.fn.usedEnd = true
			return "goto end\n"
		}
		l := g.blocks[g.rng.Intn(len(g.blocks))]
		l.used = true
		if l == g.fn.end {
			g.fn.usedEnd = true
		}
		return "goto " + l.name + "\n"
	}
	return g.event(vars...)
}

// stmt returns a statement of the nest.
func (g *gen) stmt(depth int) string { return g.stmtVars(depth, nil) }

func (g *gen) stmtVars(depth int, vars []string) string {
	k := g.rng.Intn(100)
	switch {
	case k < 30 && depth < 5:
		return g.loop(depth, vars)
	case k < 34 && depth < 5:
		return g.switchStmt(depth, vars)
	case k < 50:
		return fmt.Sprintf("if %s {\n%s}\n", g.cond(vars), indent(g.jumpOrEvent(vars)))
	case k < 56:
		return fmt.Sprintf("if %s {\n%s} else {\n%s}\n", g.cond(vars), indent(g.block(depth+1, true)), indent(g.block(depth+1, true)))
	case k < 60:
		return "acc++\n"
	case k < 63:
		return fmt.Sprintf("defer fmt.Println(\"defer\", %d, acc)\n", g.next())
	case k < 67 && len(vars) > 0:
		v := vars[g.rng.Intn(len(vars))]
		return fmt.Sprintf("acc += %s %% 5\n", v)
	case k < 76:
		return g.jump(vars)
	}
	return g.event(vars...)
}

func (g *gen) jumpOrEvent(vars []string) string {
	if g.chance(70) {
		return g.jump(vars)
	}
	return g.event(vars...) + g.jump(vars)
}

func (g *gen) switchStmt(depth int, vars []string) string {
	l := &label{name: fmt.Sprintf("L%d", g.next())}
	g.stack = append(g.stack, l)
	v := "acc"
	if len(vars) > 0 {
		v = vars[len(vars)-1]
	}
	var b strings.Builder
	fmt.Fprintf(&b, "switch %s %% 3 {\n", v)
	for c := range 2 {
		fmt.Fprintf(&b, "case %d:\n%s", c, indent(g.blockVars(depth+1, vars)))
	}
	if g.chance(60) {
		b.WriteString("default:\n" + indent(g.blockVars(depth+1, vars)))
	}
	b.WriteString("}\n")
	g.stack = g.stack[:len(g.stack)-1]
	if l.used {
		return l.name + ":\n" + b.String()
	}
	return b.String()
}

func (g *gen) blockVars(depth int, vars []string) string {
	var b strings.Builder
	n := 1 + g.rng.Intn(2)
	for range n {
		b.WriteString(g.stmtVars(depth, vars))
	}
	return b.String()
}

// loop returns a loop: range over a func (most), range over an int, or a 3-clause for.
func (g *gen) loop(depth int, vars []string) string {
	l := &label{name: fmt.Sprintf("L%d", g.next()), loop: true}
	id := g.next()
	var head string
	var inner, strs []string
	rf := false
	switch g.rng.Intn(10) {
	case 0, 1, 2, 3:
		x := fmt.Sprintf("x%d", id)
		head = fmt.Sprintf("for %s := range it1(%d)", x, 1+g.rng.Intn(3))
		inner = []string{x}
		rf = true
	case 4:
		x, s := fmt.Sprintf("x%d", id), fmt.Sprintf("s%d", id)
		head = fmt.Sprintf("for %s, %s := range it2(%d)", x, s, 1+g.rng.Intn(3))
		inner = []string{x}
		strs = []string{s}
		rf = true
	case 5:
		head = fmt.Sprintf("for range it0(%d)", 1+g.rng.Intn(3))
		rf = true
	case 6:
		head = fmt.Sprintf("for range it1(%d)", 1+g.rng.Intn(3))
		rf = true
	case 7:
		x := fmt.Sprintf("n%d", id)
		head = fmt.Sprintf("for %s := range %d", x, 1+g.rng.Intn(3))
		inner = []string{x}
	case 8:
		x := fmt.Sprintf("i%d", id)
		head = fmt.Sprintf("for %s := 0; %s < %d; %s++", x, x, 1+g.rng.Intn(3), x)
		inner = []string{x}
	default:
		// the assignment form: for acc = range it1(n) is not allowed to run forever either
		x := fmt.Sprintf("a%d", id)
		head = fmt.Sprintf("for %s = range it1(%d)", "acc", 1+g.rng.Intn(3))
		_ = x
		rf = true
	}
	g.stack = append(g.stack, l)
	if rf {
		g.inRF++
	}
	all := append(append([]string{}, vars...), inner...)
	var body strings.Builder
	for _, v := range append(append([]string{}, inner...), strs...) {
		body.WriteString(fmt.Sprintf("fmt.Println(\"body\", %d, %s)\n", id, v))
	}
	if len(inner)+len(strs) == 0 {
		body.WriteString(fmt.Sprintf("fmt.Println(\"body\", %d)\n", id))
	}
	if g.chance(15) && len(inner) > 0 {
		body.WriteString(fmt.Sprintf("fs = append(fs, func() int { return %s })\n", inner[0]))
	}
	end := &label{name: fmt.Sprintf("b%d", g.next())}
	g.blocks = append(g.blocks, end)
	n := 1 + g.rng.Intn(3)
	if depth >= 4 {
		n = 1
	}
	for range n {
		body.WriteString(g.stmtVars(depth+1, all))
	}
	g.blocks = g.blocks[:len(g.blocks)-1]
	if end.used {
		body.WriteString(end.name + ":\n")
	}
	if rf {
		g.inRF--
	}
	g.stack = g.stack[:len(g.stack)-1]
	text := head + " {\n" + indent(body.String()) + "}\n"
	if l.used {
		text = l.name + ":\n" + text
	}
	if strings.Contains(body.String(), "fs = append") {
		// The closures that keep a loop variable run after the loop.
		text = "{\n" + indent("var fs []func() int\n"+text+"for _, f := range fs {\n\tfmt.Println(\"kept\", f())\n}\n") + "}\n"
	}
	return text
}
